import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import Sidebar from "../components/Sidebar";

function Lesson() {
  const { lessonId } = useParams();
  const navigate = useNavigate();
  const user = JSON.parse(localStorage.getItem("user"));

  const [lesson, setLesson] = useState(null);
  const [tutors, setTutors] = useState([]);
  const [sessions, setSessions] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!user) return;

    async function load() {
      try {
        // Attempt to fetch lesson details (backend may expose a similar endpoint)
        const res = await fetch(`http://localhost:8080/lessons/${lessonId}/${user.id}`);
        const data = await res.json();

        // Expecting { lesson, tutors, sessions }
        setLesson(data.lesson || data);
        setTutors(data.tutors || data.lessonTutors || []);
        setSessions(data.sessions || []);
      } catch (err) {
        console.error("Lesson load error:", err);
      } finally {
        setLoading(false);
      }
    }

    load();
  }, [lessonId, user]);

  if (!user) return <h1 style={{ color: "white" }}>Please log in</h1>;

  async function handleSignup(sessionId) {
    try {
      const res = await fetch("http://localhost:8080/session_signups", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ session_id: sessionId, user_id: user.id }),
      });

      const data = await res.json();
      if (res.ok) {
        alert(data.message || "Signed up successfully");
        navigate("/dashboard");
      } else {
        alert(data.message || "Could not sign up");
      }
    } catch (err) {
      console.error(err);
      alert("Signup failed. Try again later.");
    }
  }

  return (
    <div className="dashboard-page">
      <Sidebar />

      <main className="dashboard-main">
        {loading ? (
          <p className="dashboard-loading">Loading lesson...</p>
        ) : (
          <div>
            <header className="dashboard-header">
              <div>
                <h1>{lesson?.title || "Lesson"}</h1>
                <p className="dashboard-subtitle">{lesson?.description}</p>
              </div>

              <div className="dashboard-header-actions">
                <button className="ghost-btn" onClick={() => navigate(-1)}>
                  Back
                </button>
              </div>
            </header>

            <section className="dashboard-panel">
              <h2>Tutors for this lesson</h2>
              {tutors.length === 0 ? (
                <p className="empty-text">No tutors listed for this lesson.</p>
              ) : (
                <div className="tutor-grid">
                  {tutors.map((t) => (
                    <div key={t.id} className="card">
                      <h3>{t.name}</h3>
                      <p>{t.bio}</p>
                      <p className="small muted">Specializes in this lesson</p>
                    </div>
                  ))}
                </div>
              )}
            </section>

            <section className="dashboard-panel">
              <h2>Upcoming sessions</h2>
              {sessions.length === 0 ? (
                <p className="empty-text">No sessions scheduled yet.</p>
              ) : (
                <ul className="sessions-list">
                  {sessions.map((s) => (
                    <li key={s.id} className="session-item card">
                      <div>
                        <p className="session-subject">{s.subject || lesson?.title}</p>
                        <p className="session-tutor">Tutor: {s.tutor_name || s.tutorName || "—"}</p>
                        <p className="small muted">Spots: {s.signed_up || 0}/{s.max_spots || s.maxSpots || 7}</p>
                      </div>
                      <div className="session-actions">
                        <p className="session-time">{new Date(s.session_time).toLocaleString()}</p>
                        <button
                          className="primary-btn"
                          onClick={() => handleSignup(s.id)}
                        >
                          Join
                        </button>
                      </div>
                    </li>
                  ))}
                </ul>
              )}
            </section>
          </div>
        )}
      </main>
    </div>
  );
}

export default Lesson;
